// Prototype: editable draft copies own both their list and mutable lines.
package boundary;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;

public final class OrderDraft {
    private final String title;
    private final List<Line> lines = new ArrayList<>();
    public static final class Line {
        private final String name;
        private int units;
        public Line(String name, int units) { this.name = text(name); setUnits(units); }
        public String name() { return name; }
        public int units() { return units; }
        public void setUnits(int value) {
            if (value < 1 || value > 1000) throw new IllegalArgumentException("line units must be 1..1000");
            units = value;
        }
    }
    private static String text(String value) {
        Objects.requireNonNull(value, "text");
        if (value.isBlank() || value.contains("\n") || value.contains("\r"))
            throw new IllegalArgumentException("text must be a nonblank single line");
        return value;
    }
    public OrderDraft(String title, List<Line> source) {
        this.title = text(title);
        Objects.requireNonNull(source, "lines");
        for (Line line : source) {
            Objects.requireNonNull(line, "line");
            lines.add(new Line(line.name(), line.units()));
        }
    }
    public String title() { return title; }
    /** The list structure is read-only, but its Line elements remain editable. */
    public List<Line> lines() { return Collections.unmodifiableList(lines); }
    public void add(String name, int units) { lines.add(new Line(name, units)); }
    public int totalUnits() {
        int total = 0;
        for (Line line : lines) total = Math.addExact(total, line.units());
        return total;
    }
    public OrderDraft copy() { return new OrderDraft(title, lines); }
    public OrderDraft copyWithTitle(String value) { return new OrderDraft(value, lines); }
}

// Adapter: convert the foreign request and validate its response at one boundary.
package boundary;
import java.math.BigDecimal;
import java.util.Objects;

public final class PriceAdapter implements PricePort {
    private final LegacyPrice legacy;
    public PriceAdapter(LegacyPrice legacy) { this.legacy = Objects.requireNonNull(legacy, "legacy"); }
    public BigDecimal total(int units) {
        if (units < 0 || units > 1000) throw new IllegalArgumentException("units must be 0..1000");
        String result = Objects.requireNonNull(legacy.totalFor(Integer.toString(units)), "legacy total");
        if (!result.matches("USD [0-9]+\\.[0-9]{2}"))
            throw new IllegalArgumentException("legacy total must be USD with two decimals");
        return new BigDecimal(result.substring(4));
    }
}

package boundary;
import java.math.BigDecimal;
@FunctionalInterface
public interface PricePort {
    /** Total for 0..1000 units, non-null/nonnegative USD with scale exactly two. */
    BigDecimal total(int units);
}

// Facade: snapshot, validate quantity, obtain one typed price, return a value.
package boundary;
import java.math.BigDecimal;
import java.util.Objects;

public final class QuoteFacade {
    private final PricePort prices;
    public QuoteFacade(PricePort prices) { this.prices = Objects.requireNonNull(prices, "prices"); }
    public record Quote(String title, int units, BigDecimal total) {
        public Quote {
            Objects.requireNonNull(title, "title");
            Objects.requireNonNull(total, "total");
            if (title.isBlank() || title.contains("\n") || title.contains("\r") ||
                units < 0 || units > 1000 || total.signum() < 0 || total.scale() != 2)
                throw new IllegalArgumentException("invalid quote");
        }
        public String render() { return title + ": " + units + " units = USD " + total.toPlainString() + "\n"; }
    }
    public Quote quote(OrderDraft draft) {
        Objects.requireNonNull(draft, "draft");
        OrderDraft snapshot = draft.copy();
        int units = snapshot.totalUnits();
        if (units > 1000) throw new IllegalArgumentException("total units must be 0..1000");
        return new Quote(snapshot.title(), units, prices.total(units));
    }
}

